export const vendasNegociacaoQuestions: Question[] = [
  {"id": "vendas-negociacao-conc-v1-mc-i-01", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "Etapas da venda", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Na etapa de sondagem (ou levantamento de necessidades) de um atendimento bancário, o principal objetivo do vendedor é", "alternatives": [{"id": "A", "text": "compreender as necessidades, objetivos e o perfil do cliente antes de oferecer qualquer produto"}, {"id": "B", "text": "apresentar o maior número possível de produtos para aumentar as chances de venda"}, {"id": "C", "text": "fechar a venda o mais rápido possível, antes que o cliente desista"}, {"id": "D", "text": "contornar objeções que o cliente ainda não manifestou"}, {"id": "E", "text": "oferecer o produto com a maior meta comercial da agência"}], "correctAnswer": "A", "explanation": "A sondagem é a etapa em que o vendedor faz perguntas e escuta o cliente para entender sua situação, necessidades e objetivos. Ela orienta a apresentação de soluções adequadas e reduz o risco de venda inadequada.", "alternativeExplanations": {"A": "Correto. A sondagem serve para entender o cliente e só então recomendar a solução adequada.", "B": "Apresentar tudo sem entender o cliente é o oposto da sondagem e tende a afastá-lo.", "C": "Pressa no fechamento sem diagnóstico gera vendas inadequadas e insatisfação.", "D": "Objeções são tratadas quando surgem, em etapa posterior.", "E": "A recomendação deve atender o cliente, não apenas a meta da agência."}, "tags": ["tecnicas-de-vendas", "sondagem", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["tecnicas-de-vendas", "sondagem"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-i-02", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Direito do consumidor", "subtopic": "Práticas abusivas", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Um gerente condiciona a liberação de um empréstimo à contratação de um seguro de vida pelo cliente. Essa prática é chamada de", "alternatives": [{"id": "A", "text": "venda cruzada (cross-selling), permitida desde que haja meta"}, {"id": "B", "text": "venda casada, vedada pelo Código de Defesa do Consumidor"}, {"id": "C", "text": "up-selling, uma técnica legítima de aumento de ticket"}, {"id": "D", "text": "fidelização, prática recomendada no marketing de relacionamento"}, {"id": "E", "text": "pacote de serviços, sempre permitido aos bancos"}], "correctAnswer": "B", "explanation": "O art. 39, I, do Código de Defesa do Consumidor proíbe condicionar o fornecimento de um produto ou serviço ao fornecimento de outro, a chamada venda casada. O cliente pode contratar o seguro, mas por escolha própria.", "alternativeExplanations": {"A": "Cross-selling é oferecer produto complementar sem impor condição; condicionar é venda casada.", "B": "Correto. Condicionar um produto à compra de outro é venda casada, proibida pelo art. 39 do CDC.", "C": "Up-selling é oferecer versão superior, e não condicionar um produto a outro.", "D": "Fidelização se constrói com valor para o cliente, não com imposição.", "E": "Pacotes são permitidos quando opcionais; condicionar o crédito ao seguro é abusivo."}, "tags": ["cdc", "venda-casada", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cdc", "venda-casada"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-i-03", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "Cross-selling e up-selling", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Um cliente que acabou de abrir conta corrente recebe a oferta de um cartão de crédito com anuidade compatível com seu perfil. Essa estratégia de oferecer um produto complementar é conhecida como", "alternatives": [{"id": "A", "text": "up-selling"}, {"id": "B", "text": "venda casada"}, {"id": "C", "text": "venda cruzada (cross-selling)"}, {"id": "D", "text": "pós-venda"}, {"id": "E", "text": "prospecção"}], "correctAnswer": "C", "explanation": "Cross-selling é a oferta de produtos complementares ao que o cliente já contratou, como cartão para quem abriu conta. Up-selling é a oferta de versão superior. As duas são legítimas quando atendem à necessidade do cliente e não há imposição.", "alternativeExplanations": {"A": "Up-selling é oferecer uma versão superior do mesmo produto, como um cartão de categoria mais alta.", "B": "Venda casada exige condicionar um produto ao outro, o que não ocorre aqui.", "C": "Correto. Oferecer um produto complementar ao que o cliente já tem é cross-selling.", "D": "Pós-venda é o acompanhamento depois da compra.", "E": "Prospecção é a busca de novos clientes, e este já é cliente."}, "tags": ["cross-selling", "tecnicas-de-vendas", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cross-selling", "tecnicas-de-vendas"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-i-04", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Qualidade no atendimento", "subtopic": "Escuta ativa", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Durante o atendimento, o funcionário que pratica a escuta ativa", "alternatives": [{"id": "A", "text": "interrompe o cliente para agilizar o atendimento"}, {"id": "B", "text": "prepara a resposta enquanto o cliente ainda está falando"}, {"id": "C", "text": "evita fazer perguntas para não parecer inseguro"}, {"id": "D", "text": "demonstra atenção, faz perguntas de esclarecimento e confirma o que entendeu da fala do cliente"}, {"id": "E", "text": "concorda com tudo para evitar conflito"}], "correctAnswer": "D", "explanation": "A escuta ativa consiste em prestar atenção genuína, não interromper, fazer perguntas para esclarecer e resumir ou parafrasear o que foi dito para confirmar o entendimento. Ela cria confiança e evita mal-entendidos.", "alternativeExplanations": {"A": "Interromper o cliente é o oposto da escuta ativa.", "B": "Pensar na resposta durante a fala tira a atenção do que o cliente diz.", "C": "Perguntas de esclarecimento são parte essencial da escuta ativa.", "D": "Correto. Escuta ativa envolve atenção real, perguntas e confirmação do entendimento.", "E": "Concordar sem compreender não é escuta ativa."}, "tags": ["escuta-ativa", "atendimento", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["escuta-ativa", "atendimento"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-i-05", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Direito do consumidor", "subtopic": "Direito de arrependimento", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Um cliente contratou um produto pelo aplicativo do banco, fora do estabelecimento comercial. Pelo Código de Defesa do Consumidor, ele pode desistir da contratação no prazo de", "alternatives": [{"id": "A", "text": "30 dias, para qualquer contratação"}, {"id": "B", "text": "24 horas após a contratação"}, {"id": "C", "text": "90 dias, se o produto for durável"}, {"id": "D", "text": "não há prazo, pois a contratação digital é irrevogável"}, {"id": "E", "text": "7 dias, a contar da assinatura ou do recebimento do produto ou serviço"}], "correctAnswer": "E", "explanation": "O art. 49 do CDC permite ao consumidor desistir, em 7 dias, de contratações feitas fora do estabelecimento comercial, como por telefone, internet ou aplicativo, com devolução dos valores pagos.", "alternativeExplanations": {"A": "30 dias não é o prazo do direito de arrependimento.", "B": "O prazo legal é maior: 7 dias.", "C": "90 dias é prazo de reclamação por vícios em produtos duráveis, outro instituto.", "D": "A contratação digital é feita fora do estabelecimento e admite arrependimento.", "E": "Correto. O art. 49 do CDC garante o direito de arrependimento em 7 dias nas contratações fora do estabelecimento."}, "tags": ["cdc", "arrependimento", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cdc", "arrependimento"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-i-06", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Marketing", "subtopic": "Composto de marketing", "difficulty": "iniciante", "type": "multiple-choice", "statement": "O composto de marketing, conhecido como 4Ps, é formado por", "alternatives": [{"id": "A", "text": "produto, preço, praça (distribuição) e promoção"}, {"id": "B", "text": "pessoas, processos, prova física e produtividade"}, {"id": "C", "text": "planejamento, pesquisa, pós-venda e preço"}, {"id": "D", "text": "produto, propaganda, pessoas e parceria"}, {"id": "E", "text": "preço, prazo, pagamento e prestação"}], "correctAnswer": "A", "explanation": "O composto de marketing (mix de marketing), de McCarthy, reúne produto, preço, praça (distribuição) e promoção. Em serviços, costuma ser ampliado com pessoas, processos e evidência física.", "alternativeExplanations": {"A": "Correto. Os 4Ps de McCarthy são produto, preço, praça e promoção.", "B": "Esses elementos aparecem nos Ps estendidos de serviços, não nos 4Ps clássicos.", "C": "Planejamento e pesquisa são atividades de marketing, não os 4Ps.", "D": "Propaganda faz parte de promoção; pessoas e parceria não estão nos 4Ps.", "E": "Prazo e formas de pagamento são detalhes do preço, não Ps distintos."}, "tags": ["marketing", "4ps", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["marketing", "4ps"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-i-07", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Atendimento", "subtopic": "Atendimento prioritário", "difficulty": "iniciante", "type": "multiple-choice", "statement": "De acordo com a legislação de atendimento prioritário, os bancos devem dar atendimento preferencial, entre outros, a", "alternatives": [{"id": "A", "text": "clientes de segmento alta renda"}, {"id": "B", "text": "pessoas idosas com 60 anos ou mais, gestantes e pessoas com deficiência"}, {"id": "C", "text": "clientes com maior tempo de relacionamento"}, {"id": "D", "text": "servidores públicos em horário de expediente"}, {"id": "E", "text": "pessoas que chegarem antes da abertura da agência"}], "correctAnswer": "B", "explanation": "A Lei 10.048/2000 garante atendimento prioritário a pessoas com deficiência, idosos com 60 anos ou mais, gestantes, lactantes, pessoas com crianças de colo e pessoas com obesidade, e outras leis ampliaram esse rol. A prioridade se baseia em condições pessoais, não em segmento comercial.", "alternativeExplanations": {"A": "Prioridade legal não depende de renda ou segmento comercial.", "B": "Correto. A Lei 10.048/2000 garante atendimento prioritário a esses grupos, entre outros.", "C": "Tempo de relacionamento não gera prioridade legal.", "D": "Não há prioridade legal para servidores públicos nessa condição.", "E": "Ordem de chegada não é critério de prioridade legal."}, "tags": ["atendimento-prioritario", "legislacao", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["atendimento-prioritario", "legislacao"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-m-01", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Negociação", "subtopic": "Método de Harvard", "difficulty": "medio", "type": "multiple-choice", "statement": "Entre os princípios da negociação baseada em princípios (método de Harvard), está", "alternatives": [{"id": "A", "text": "começar com uma proposta extrema para ter margem de concessão"}, {"id": "B", "text": "tratar a pessoa e o problema como uma coisa só"}, {"id": "C", "text": "concentrar-se nos interesses das partes, e não em suas posições"}, {"id": "D", "text": "evitar critérios objetivos para não engessar o acordo"}, {"id": "E", "text": "buscar uma única solução desde o início"}], "correctAnswer": "C", "explanation": "O método de Harvard (Fisher e Ury) propõe quatro princípios: separar as pessoas do problema; focar nos interesses, não nas posições; inventar opções de ganho mútuo; e insistir em critérios objetivos.", "alternativeExplanations": {"A": "Ancoragem agressiva é tática posicional, não princípio do método de Harvard.", "B": "O método recomenda separar as pessoas do problema.", "C": "Correto. Focar em interesses permite encontrar soluções que atendam ambos os lados.", "D": "O método defende o uso de critérios objetivos.", "E": "O método recomenda criar várias opções de ganho mútuo antes de decidir."}, "tags": ["negociacao", "harvard", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["negociacao", "harvard"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-m-02", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Negociação", "subtopic": "BATNA", "difficulty": "medio", "type": "multiple-choice", "statement": "Na teoria da negociação, a sigla BATNA (em português, MAANA) designa", "alternatives": [{"id": "A", "text": "o preço mínimo de tabela definido pela empresa"}, {"id": "B", "text": "a zona em que as propostas das duas partes se sobrepõem"}, {"id": "C", "text": "a primeira oferta feita na negociação"}, {"id": "D", "text": "a melhor alternativa à negociação de um acordo, ou seja, o que a parte fará se não houver acordo"}, {"id": "E", "text": "o acordo final assinado pelas partes"}], "correctAnswer": "D", "explanation": "BATNA (best alternative to a negotiated agreement) é a melhor alternativa que a parte tem caso a negociação fracasse. Conhecer a própria BATNA ajuda a não aceitar acordos piores do que ela e fortalece a posição de quem negocia.", "alternativeExplanations": {"A": "Preço de tabela é referência comercial, não a alternativa ao acordo.", "B": "Essa é a ZOPA (zona de possível acordo).", "C": "A primeira oferta é a ancoragem, não a BATNA.", "D": "Correto. A BATNA define até onde vale negociar: um acordo pior que ela não compensa.", "E": "A BATNA é justamente o que existe se não houver acordo."}, "tags": ["negociacao", "batna", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["negociacao", "batna"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-m-03", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "SPIN Selling", "difficulty": "medio", "type": "multiple-choice", "statement": "No método SPIN Selling, as perguntas de implicação têm como objetivo", "alternatives": [{"id": "A", "text": "levantar dados gerais sobre a situação atual do cliente"}, {"id": "B", "text": "identificar dificuldades e insatisfações do cliente"}, {"id": "C", "text": "fazer o cliente expressar o valor da solução"}, {"id": "D", "text": "encerrar a venda com uma proposta de preço"}, {"id": "E", "text": "levar o cliente a perceber as consequências do problema que ele enfrenta"}], "correctAnswer": "E", "explanation": "SPIN é a sigla de Situação, Problema, Implicação e Necessidade de solução. As perguntas de implicação exploram as consequências do problema, aumentando a percepção de urgência e de valor da solução.", "alternativeExplanations": {"A": "Esse é o papel das perguntas de situação.", "B": "Esse é o papel das perguntas de problema.", "C": "Esse é o papel das perguntas de necessidade de solução.", "D": "SPIN é um método de perguntas, e o fechamento é etapa posterior.", "E": "Correto. As perguntas de implicação ampliam a percepção do impacto do problema."}, "tags": ["spin-selling", "tecnicas-de-vendas", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["spin-selling", "tecnicas-de-vendas"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-m-04", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Qualidade no atendimento", "subtopic": "Dimensões da qualidade em serviços", "difficulty": "medio", "type": "multiple-choice", "statement": "No modelo SERVQUAL, a dimensão que corresponde à capacidade de prestar o serviço prometido de forma precisa e consistente é a", "alternatives": [{"id": "A", "text": "confiabilidade"}, {"id": "B", "text": "tangibilidade"}, {"id": "C", "text": "empatia"}, {"id": "D", "text": "responsividade"}, {"id": "E", "text": "segurança"}], "correctAnswer": "A", "explanation": "O SERVQUAL avalia a qualidade em serviços em cinco dimensões: tangibilidade, confiabilidade, responsividade (presteza), segurança e empatia. Confiabilidade é entregar o serviço prometido de forma correta e consistente.", "alternativeExplanations": {"A": "Correto. Confiabilidade é cumprir o prometido com exatidão.", "B": "Tangibilidade se refere a instalações, equipamentos e aparência dos funcionários.", "C": "Empatia é a atenção individualizada ao cliente.", "D": "Responsividade é a disposição de ajudar e atender com rapidez.", "E": "Segurança envolve conhecimento, cortesia e capacidade de transmitir confiança."}, "tags": ["servqual", "qualidade", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["servqual", "qualidade"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-m-05", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Marketing de serviços", "subtopic": "Características dos serviços", "difficulty": "medio", "type": "multiple-choice", "statement": "A característica dos serviços que indica que eles não podem ser estocados para uso posterior, como um horário de atendimento não utilizado, é a", "alternatives": [{"id": "A", "text": "intangibilidade"}, {"id": "B", "text": "perecibilidade"}, {"id": "C", "text": "inseparabilidade"}, {"id": "D", "text": "variabilidade"}, {"id": "E", "text": "tangibilidade"}], "correctAnswer": "B", "explanation": "Os serviços têm quatro características clássicas: intangibilidade, inseparabilidade, variabilidade (heterogeneidade) e perecibilidade. A perecibilidade significa que o serviço não pode ser estocado.", "alternativeExplanations": {"A": "Intangibilidade é não poder ser visto ou tocado antes da compra.", "B": "Correto. Serviços perecem: a capacidade não usada não pode ser guardada.", "C": "Inseparabilidade é a produção e o consumo ocorrerem ao mesmo tempo.", "D": "Variabilidade é a qualidade depender de quem presta o serviço, quando e onde.", "E": "Tangibilidade é dimensão de qualidade, não característica de perecimento."}, "tags": ["marketing-de-servicos", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["marketing-de-servicos"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-m-06", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Marketing de relacionamento", "subtopic": "CRM", "difficulty": "medio", "type": "multiple-choice", "statement": "Um banco usa um sistema de CRM (Customer Relationship Management). O principal objetivo desse sistema é", "alternatives": [{"id": "A", "text": "substituir o atendimento humano por robôs em todos os canais"}, {"id": "B", "text": "controlar a contabilidade e os impostos da instituição"}, {"id": "C", "text": "reunir informações sobre os clientes para personalizar o relacionamento e as ofertas"}, {"id": "D", "text": "calcular a taxa Selic utilizada nas operações de crédito"}, {"id": "E", "text": "enviar a mesma oferta a todos os clientes ao mesmo tempo"}], "correctAnswer": "C", "explanation": "O CRM é uma estratégia apoiada por tecnologia que reúne o histórico, as preferências e as interações de cada cliente, para personalizar o atendimento, antecipar necessidades e aumentar a retenção e o valor do cliente ao longo do tempo.", "alternativeExplanations": {"A": "Automação pode existir, mas não é o objetivo central do CRM.", "B": "Isso é função de sistemas contábeis e fiscais.", "C": "Correto. O CRM integra dados dos clientes para apoiar um relacionamento personalizado e duradouro.", "D": "A Selic é definida pelo Copom, não calculada pelo CRM.", "E": "Ofertas iguais para todos são o oposto da personalização que o CRM busca."}, "tags": ["crm", "marketing-de-relacionamento", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["crm", "marketing-de-relacionamento"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-m-07", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Ética e conduta", "subtopic": "Adequação de produtos (suitability)", "difficulty": "medio", "type": "multiple-choice", "statement": "Antes de recomendar investimentos, a instituição deve verificar se o produto é adequado ao perfil do cliente. Esse procedimento, regulado pela CVM, é conhecido como", "alternatives": [{"id": "A", "text": "know your employee (conheça seu funcionário)"}, {"id": "B", "text": "cross-selling"}, {"id": "C", "text": "benchmarking"}, {"id": "D", "text": "suitability (análise do perfil do investidor)"}, {"id": "E", "text": "compliance tributário"}], "correctAnswer": "D", "explanation": "A regra de suitability (hoje na Resolução CVM 30/2021) exige que quem recomenda produtos de investimento verifique se eles são adequados aos objetivos, à situação financeira e ao conhecimento do cliente, que deve passar pela análise de perfil.", "alternativeExplanations": {"A": "KYE é procedimento de PLD voltado a funcionários.", "B": "Cross-selling é estratégia de vendas, não análise de adequação.", "C": "Benchmarking é comparar práticas com referências do mercado.", "D": "Correto. Suitability é verificar se o produto é adequado aos objetivos, à situação financeira e ao conhecimento do cliente.", "E": "Compliance tributário trata do cumprimento de obrigações fiscais."}, "tags": ["suitability", "etica", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["suitability", "etica"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-a-01", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Negociação", "subtopic": "ZOPA", "difficulty": "avancado", "type": "multiple-choice", "statement": "Na negociação de um empréstimo, o banco aceita taxas a partir de 1,5% ao mês e o cliente aceita pagar no máximo 1,8% ao mês. Nesse caso, a zona de possível acordo (ZOPA)", "alternatives": [{"id": "A", "text": "não existe, pois as partes têm limites diferentes"}, {"id": "B", "text": "corresponde apenas ao valor de 1,65% ao mês"}, {"id": "C", "text": "vai de 0% a 1,5% ao mês"}, {"id": "D", "text": "vai de 1,8% a 3% ao mês"}, {"id": "E", "text": "existe e vai de 1,5% a 1,8% ao mês"}], "correctAnswer": "E", "explanation": "A ZOPA (zona de possível acordo) é o intervalo em que os limites das partes se sobrepõem. Se o banco aceita a partir de 1,5% e o cliente aceita até 1,8%, qualquer taxa nesse intervalo pode gerar acordo.", "alternativeExplanations": {"A": "Ter limites diferentes é normal; a ZOPA existe quando eles se sobrepõem.", "B": "A ZOPA é um intervalo, não um único ponto.", "C": "Abaixo de 1,5% o banco não aceita, então não há acordo possível ali.", "D": "Acima de 1,8% o cliente não aceita.", "E": "Correto. A ZOPA é o intervalo entre o mínimo aceitável de uma parte e o máximo da outra."}, "tags": ["negociacao", "zopa", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["negociacao", "zopa"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-a-02", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Negociação", "subtopic": "Negociação integrativa", "difficulty": "avancado", "type": "multiple-choice", "statement": "Uma negociação integrativa difere de uma negociação distributiva porque", "alternatives": [{"id": "A", "text": "busca ampliar o valor em jogo, explorando interesses diversos para gerar ganhos para ambas as partes"}, {"id": "B", "text": "parte do pressuposto de que o ganho de um lado é necessariamente a perda do outro"}, {"id": "C", "text": "ocorre apenas quando há um único tema em discussão, como o preço"}, {"id": "D", "text": "dispensa a troca de informações entre as partes"}, {"id": "E", "text": "é sempre mais rápida e exige menos preparação"}], "correctAnswer": "A", "explanation": "Na negociação distributiva, as partes disputam um valor fixo (ganha-perde). Na integrativa, elas exploram interesses, prioridades e variáveis diferentes, como prazo, garantias e volume, para criar valor e chegar a acordos ganha-ganha.", "alternativeExplanations": {"A": "Correto. Na integrativa, as partes criam valor; na distributiva, disputam um valor fixo.", "B": "Essa é a lógica da negociação distributiva (soma zero).", "C": "Temas únicos favorecem a distributiva; a integrativa costuma envolver várias variáveis.", "D": "A integrativa depende de troca de informações sobre interesses.", "E": "A integrativa costuma exigir mais preparação e diálogo."}, "tags": ["negociacao", "integrativa", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["negociacao", "integrativa"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-a-03", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Marketing de relacionamento", "subtopic": "Valor do cliente", "difficulty": "avancado", "type": "multiple-choice", "statement": "Um banco decide investir mais na retenção de clientes do que na conquista de novos. O indicador que melhor justifica essa decisão é o", "alternatives": [{"id": "A", "text": "número de agências físicas"}, {"id": "B", "text": "valor do cliente ao longo do tempo (Customer Lifetime Value)"}, {"id": "C", "text": "índice de inadimplência de pessoas jurídicas"}, {"id": "D", "text": "total de anúncios veiculados no mês"}, {"id": "E", "text": "prazo médio de atendimento no caixa"}], "correctAnswer": "B", "explanation": "O Customer Lifetime Value (CLV ou LTV) estima o resultado que um cliente gera durante todo o relacionamento. Como conquistar clientes costuma custar mais do que retê-los, um CLV alto justifica investir em retenção e fidelização.", "alternativeExplanations": {"A": "O número de agências não mede o valor gerado pelos clientes.", "B": "Correto. O CLV mostra o valor que um cliente gera durante todo o relacionamento.", "C": "Inadimplência mede risco de crédito, não valor do relacionamento.", "D": "Volume de anúncios não mede o retorno de reter clientes.", "E": "É um indicador operacional, não de valor do cliente."}, "tags": ["ltv", "marketing-de-relacionamento", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["ltv", "marketing-de-relacionamento"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-a-04", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "Tratamento de objeções", "difficulty": "avancado", "type": "multiple-choice", "statement": "Um cliente afirma: 'Essa taxa está cara, o outro banco me ofereceu menos'. A atitude MAIS adequada do vendedor, segundo as boas práticas de tratamento de objeções, é", "alternatives": [{"id": "A", "text": "dizer que o outro banco não é confiável"}, {"id": "B", "text": "ignorar o comentário e seguir com o fechamento"}, {"id": "C", "text": "acolher a objeção, entender as condições da outra oferta e mostrar o valor total da proposta, sem desqualificar o concorrente"}, {"id": "D", "text": "reduzir imediatamente a taxa ao menor valor permitido"}, {"id": "E", "text": "encerrar o atendimento, pois o cliente já decidiu"}], "correctAnswer": "C", "explanation": "Boas práticas de vendas tratam a objeção como pedido de mais informação: ouvir, entender o ponto do cliente (prazo, tarifas, garantias, CET), comparar de forma justa e mostrar o valor total da proposta, sem atacar a concorrência.", "alternativeExplanations": {"A": "Desqualificar o concorrente é antiético e reduz a credibilidade do vendedor.", "B": "Ignorar a objeção deixa a dúvida sem resposta e afasta o cliente.", "C": "Correto. Objeções são sinais de interesse e devem ser exploradas com escuta e argumentos de valor.", "D": "Ceder de imediato, sem entender a comparação, destrói margem desnecessariamente.", "E": "A objeção indica interesse; encerrar desperdiça a oportunidade."}, "tags": ["objecoes", "tecnicas-de-vendas", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["objecoes", "tecnicas-de-vendas"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-a-05", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Comportamento do consumidor", "subtopic": "Hierarquia de necessidades", "difficulty": "avancado", "type": "multiple-choice", "statement": "Segundo a hierarquia de necessidades de Maslow, um cliente que procura um seguro residencial para proteger a família está buscando atender, principalmente, a necessidade de", "alternatives": [{"id": "A", "text": "autorrealização"}, {"id": "B", "text": "estima"}, {"id": "C", "text": "fisiológica"}, {"id": "D", "text": "segurança"}, {"id": "E", "text": "social"}], "correctAnswer": "D", "explanation": "Na pirâmide de Maslow, as necessidades vão das fisiológicas às de segurança, sociais, de estima e de autorrealização. Seguros, reservas financeiras e previdência atendem principalmente à necessidade de segurança.", "alternativeExplanations": {"A": "Autorrealização é o topo da pirâmide, ligado ao desenvolvimento pessoal.", "B": "Estima envolve reconhecimento e status.", "C": "Necessidades fisiológicas são básicas, como fome e sono.", "D": "Correto. Proteção contra riscos e estabilidade estão no nível de segurança.", "E": "Necessidades sociais envolvem pertencimento e relacionamentos."}, "tags": ["maslow", "comportamento-do-consumidor", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["maslow", "comportamento-do-consumidor"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-mc-a-06", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Gestão de vendas", "subtopic": "Metas", "difficulty": "avancado", "type": "multiple-choice", "statement": "Uma meta comercial bem formulada segundo a metodologia SMART deve ser", "alternatives": [{"id": "A", "text": "simples, motivadora, aberta, rápida e temporária"}, {"id": "B", "text": "sigilosa, mutável, ambiciosa, rígida e tributável"}, {"id": "C", "text": "subjetiva, moderada, arbitrária, real e total"}, {"id": "D", "text": "sustentável, multicanal, automatizada, regional e técnica"}, {"id": "E", "text": "específica, mensurável, atingível, relevante e com prazo definido"}], "correctAnswer": "E", "explanation": "SMART vem do inglês specific, measurable, achievable, relevant e time-bound: a meta deve ser específica, mensurável, atingível, relevante e ter prazo definido. Isso facilita o acompanhamento e evita metas vagas.", "alternativeExplanations": {"A": "Essas palavras não correspondem à sigla SMART.", "B": "Essas características não fazem parte do método.", "C": "Metas subjetivas e arbitrárias contrariam o método.", "D": "Essas palavras descrevem outras coisas, não a sigla SMART.", "E": "Correto. SMART reúne essas cinco características."}, "tags": ["metas", "smart", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["metas", "smart"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-i-01", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "Pós-venda", "difficulty": "iniciante", "type": "true-false", "statement": "O pós-venda é a etapa em que o vendedor acompanha o cliente depois da compra, para verificar a satisfação e fortalecer o relacionamento.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O pós-venda inclui contato depois da compra, resolução de dúvidas e verificação da satisfação. Ele contribui para a fidelização e gera novas oportunidades de negócio.", "alternativeExplanations": {"V": "Correto. Acompanhar o cliente após a compra é exatamente o pós-venda.", "F": "Incorreto. Acompanhar o cliente após a compra é exatamente o pós-venda."}, "tags": ["pos-venda", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["pos-venda"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-i-02", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "Up-selling", "difficulty": "iniciante", "type": "true-false", "statement": "Up-selling é a estratégia de oferecer ao cliente uma versão superior ou mais completa do produto que ele está adquirindo.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "Up-selling é estimular a compra de uma versão mais completa ou de maior valor do mesmo produto, como um cartão de categoria superior, desde que adequada ao perfil do cliente.", "alternativeExplanations": {"V": "Correto. Oferecer a versão superior é a definição de up-selling.", "F": "Incorreto. Oferecer a versão superior é a definição de up-selling."}, "tags": ["up-selling", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["up-selling"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-i-03", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Direito do consumidor", "subtopic": "Informação", "difficulty": "iniciante", "type": "true-false", "statement": "O consumidor tem direito à informação adequada e clara sobre produtos e serviços, incluindo características, tributos incidentes e preço.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 6º, III, do CDC garante ao consumidor informação adequada e clara sobre os produtos e serviços, com especificação correta de quantidade, características, composição, qualidade, tributos e preço.", "alternativeExplanations": {"V": "Correto. O direito à informação clara é direito básico do consumidor.", "F": "Incorreto. O direito à informação clara é direito básico do consumidor."}, "tags": ["cdc", "informacao", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cdc", "informacao"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-i-04", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Qualidade no atendimento", "subtopic": "Satisfação do cliente", "difficulty": "iniciante", "type": "true-false", "statement": "A satisfação do cliente depende apenas da qualidade técnica do produto, sem relação com as expectativas que ele tinha antes da compra.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A satisfação resulta da comparação entre o desempenho percebido e as expectativas do cliente. Se o desempenho fica abaixo da expectativa, há insatisfação, mesmo que o produto seja tecnicamente bom.", "alternativeExplanations": {"V": "Incorreto. A satisfação compara o desempenho percebido com a expectativa.", "F": "Correto. A satisfação compara o desempenho percebido com a expectativa."}, "tags": ["satisfacao", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["satisfacao"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-i-05", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "Prospecção", "difficulty": "iniciante", "type": "true-false", "statement": "A prospecção é a etapa da venda dedicada a identificar e buscar potenciais clientes.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "Prospectar é identificar, qualificar e abordar pessoas ou empresas que podem se tornar clientes. É uma das primeiras etapas do processo de vendas.", "alternativeExplanations": {"V": "Correto. Buscar potenciais clientes é a definição de prospecção.", "F": "Incorreto. Buscar potenciais clientes é a definição de prospecção."}, "tags": ["prospeccao", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["prospeccao"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-i-06", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Marketing", "subtopic": "Segmentação", "difficulty": "iniciante", "type": "true-false", "statement": "Segmentar o mercado significa tratar todos os clientes da mesma forma, com a mesma oferta.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Segmentar é dividir o mercado em grupos com necessidades e características semelhantes, para oferecer produtos e abordagens adequados a cada grupo. Tratar todos igualmente é o marketing de massa.", "alternativeExplanations": {"V": "Incorreto. Segmentação divide o mercado em grupos com ofertas específicas.", "F": "Correto. Segmentação divide o mercado em grupos com ofertas específicas."}, "tags": ["segmentacao", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["segmentacao"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-i-07", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Direito do consumidor", "subtopic": "Publicidade", "difficulty": "iniciante", "type": "true-false", "statement": "O Código de Defesa do Consumidor proíbe a publicidade enganosa, aquela capaz de induzir o consumidor a erro sobre o produto ou serviço.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 37 do CDC proíbe a publicidade enganosa (que induz a erro sobre natureza, características, preço e outros dados) e a abusiva.", "alternativeExplanations": {"V": "Correto. A proibição está no art. 37 do CDC.", "F": "Incorreto. A proibição está no art. 37 do CDC."}, "tags": ["cdc", "publicidade", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cdc", "publicidade"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-m-01", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Negociação", "subtopic": "Método de Harvard", "difficulty": "medio", "type": "true-false", "statement": "O método de Harvard recomenda que o negociador mantenha uma posição fixa desde o início e faça concessões apenas no final.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O método de Harvard critica a barganha posicional. Ele recomenda focar nos interesses, separar as pessoas do problema, criar opções de ganho mútuo e usar critérios objetivos.", "alternativeExplanations": {"V": "Incorreto. O método de Harvard se opõe à barganha por posições.", "F": "Correto. O método de Harvard se opõe à barganha por posições."}, "tags": ["harvard", "negociacao", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["harvard", "negociacao"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-m-02", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "AIDA", "difficulty": "medio", "type": "true-false", "statement": "O modelo AIDA descreve as etapas pelas quais se busca conduzir o cliente: atenção, interesse, desejo e ação.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "AIDA é um modelo clássico de comunicação e vendas: primeiro atrair a atenção, depois despertar o interesse, criar o desejo e levar à ação, que é a compra.", "alternativeExplanations": {"V": "Correto. Atenção, interesse, desejo e ação formam a sigla AIDA.", "F": "Incorreto. Atenção, interesse, desejo e ação formam a sigla AIDA."}, "tags": ["aida", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["aida"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-m-03", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Marketing de relacionamento", "subtopic": "Retenção", "difficulty": "medio", "type": "true-false", "statement": "No marketing de relacionamento, a prioridade é a conquista contínua de novos clientes, e a retenção dos atuais tem pouca importância.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O marketing de relacionamento prioriza criar vínculos duradouros e reter clientes, já que conquistar novos costuma custar mais. A fidelização aumenta o valor gerado ao longo do tempo.", "alternativeExplanations": {"V": "Incorreto. Retenção e fidelização são o centro do marketing de relacionamento.", "F": "Correto. Retenção e fidelização são o centro do marketing de relacionamento."}, "tags": ["marketing-de-relacionamento", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["marketing-de-relacionamento"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-m-04", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Ética e conduta", "subtopic": "Conduta com clientes", "difficulty": "medio", "type": "true-false", "statement": "Pelas normas do CMN sobre relacionamento com clientes, as instituições financeiras devem oferecer produtos adequados às necessidades e ao perfil dos clientes e prestar informações claras.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A Resolução CMN 4.949/2021 estabelece princípios de conduta no relacionamento com clientes, como tratamento justo, adequação de produtos às necessidades, interesses e objetivos dos clientes, e informação clara.", "alternativeExplanations": {"V": "Correto. Adequação e transparência são princípios da norma do CMN.", "F": "Incorreto. Adequação e transparência são princípios da norma do CMN."}, "tags": ["etica", "conduta", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["etica", "conduta"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-m-05", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Atendimento", "subtopic": "Reclamações", "difficulty": "medio", "type": "true-false", "statement": "Um cliente insatisfeito que tem sua reclamação resolvida de forma rápida e cuidadosa pode se tornar mais fiel do que antes do problema.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A boa recuperação de serviço (service recovery) pode aumentar a confiança do cliente: resolver o problema com rapidez e atenção demonstra compromisso e fortalece o relacionamento.", "alternativeExplanations": {"V": "Correto. Uma boa solução de reclamações pode aumentar a fidelidade.", "F": "Incorreto. Uma boa solução de reclamações pode aumentar a fidelidade."}, "tags": ["reclamacoes", "fidelizacao", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["reclamacoes", "fidelizacao"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-m-06", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "Perguntas abertas", "difficulty": "medio", "type": "true-false", "statement": "Perguntas abertas, como 'Quais são seus planos para os próximos anos?', são indicadas para estimular o cliente a falar sobre suas necessidades.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "Perguntas abertas não podem ser respondidas com 'sim' ou 'não' e estimulam o cliente a detalhar sua situação. Elas são muito usadas na sondagem; as fechadas ajudam a confirmar informações.", "alternativeExplanations": {"V": "Correto. Perguntas abertas estimulam o cliente a se expressar.", "F": "Incorreto. Perguntas abertas estimulam o cliente a se expressar."}, "tags": ["sondagem", "perguntas", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["sondagem", "perguntas"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-m-07", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Marketing de serviços", "subtopic": "Inseparabilidade", "difficulty": "medio", "type": "true-false", "statement": "A inseparabilidade dos serviços significa que a qualidade do atendimento é sempre igual, independentemente de quem o presta.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Inseparabilidade significa que produção e consumo ocorrem ao mesmo tempo, com o prestador e o cliente presentes. A qualidade variar conforme quem presta o serviço é a característica de variabilidade.", "alternativeExplanations": {"V": "Incorreto. A afirmação confunde inseparabilidade com o oposto da variabilidade.", "F": "Correto. A afirmação confunde inseparabilidade com o oposto da variabilidade."}, "tags": ["marketing-de-servicos", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["marketing-de-servicos"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-a-01", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Negociação", "subtopic": "BATNA", "difficulty": "avancado", "type": "true-false", "statement": "Conhecer a própria BATNA (melhor alternativa a um acordo negociado) aumenta o poder de negociação, porque indica quando vale mais a pena abandonar a negociação do que fechar um mau acordo.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A BATNA serve de parâmetro: qualquer proposta pior que ela deve ser recusada. Quanto melhor a BATNA, maior o poder de negociação.", "alternativeExplanations": {"V": "Correto. A BATNA indica o ponto a partir do qual vale abandonar a negociação.", "F": "Incorreto. A BATNA indica o ponto a partir do qual vale abandonar a negociação."}, "tags": ["batna", "negociacao", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["batna", "negociacao"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-a-02", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Ética e conduta", "subtopic": "Suitability", "difficulty": "avancado", "type": "true-false", "statement": "Se o cliente insistir em aplicar em um produto inadequado ao seu perfil de investidor, a instituição está proibida de executar a ordem em qualquer hipótese.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A regulamentação da CVM permite executar a ordem nesse caso, desde que a instituição alerte o cliente sobre a ausência ou desatualização do perfil, ou sobre a inadequação, e obtenha declaração expressa de que ele está ciente.", "alternativeExplanations": {"V": "Incorreto. A operação pode ocorrer com alerta e declaração expressa do cliente.", "F": "Correto. A operação pode ocorrer com alerta e declaração expressa do cliente."}, "tags": ["suitability", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["suitability"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-a-03", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Técnicas de vendas", "subtopic": "SPIN Selling", "difficulty": "avancado", "type": "true-false", "statement": "No SPIN Selling, as perguntas de necessidade de solução levam o próprio cliente a explicitar os benefícios que uma solução traria.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "As perguntas de necessidade de solução (need-payoff) fazem o cliente verbalizar o valor e os benefícios da solução, o que torna a proposta mais convincente.", "alternativeExplanations": {"V": "Correto. Fazer o cliente expressar os benefícios é a função dessas perguntas.", "F": "Incorreto. Fazer o cliente expressar os benefícios é a função dessas perguntas."}, "tags": ["spin-selling", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["spin-selling"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-a-04", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Qualidade no atendimento", "subtopic": "SERVQUAL", "difficulty": "avancado", "type": "true-false", "statement": "No modelo SERVQUAL, a responsividade diz respeito à aparência das instalações físicas e dos materiais de comunicação.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Aparência de instalações, equipamentos e materiais corresponde à dimensão tangibilidade. Responsividade é a disposição de ajudar os clientes e prestar o serviço com presteza.", "alternativeExplanations": {"V": "Incorreto. A descrição corresponde à tangibilidade, não à responsividade.", "F": "Correto. A descrição corresponde à tangibilidade, não à responsividade."}, "tags": ["servqual", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["servqual"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-a-05", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Direito do consumidor", "subtopic": "Práticas abusivas", "difficulty": "avancado", "type": "true-false", "statement": "Enviar ao consumidor um cartão de crédito sem solicitação prévia é prática abusiva, segundo o Código de Defesa do Consumidor e a jurisprudência do STJ.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 39, III, do CDC proíbe enviar ou entregar produto ou serviço sem solicitação prévia. A Súmula 532 do STJ afirma que enviar cartão de crédito sem pedido expresso do consumidor é prática abusiva.", "alternativeExplanations": {"V": "Correto. A Súmula 532 do STJ trata exatamente dessa prática.", "F": "Incorreto. A Súmula 532 do STJ trata exatamente dessa prática."}, "tags": ["cdc", "praticas-abusivas", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cdc", "praticas-abusivas"], "origin": "nabulab"},
  {"id": "vendas-negociacao-conc-v1-vf-a-06", "area": "Concursos Bancários", "subject": "vendas-negociacao", "subjectName": "Vendas e Negociação", "topic": "Gestão de vendas", "subtopic": "Funil de vendas", "difficulty": "avancado", "type": "true-false", "statement": "No funil de vendas, o número de oportunidades tende a aumentar à medida que os contatos avançam das etapas iniciais para o fechamento.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O funil afunila: muitos contatos entram no topo, e uma parcela menor avança a cada etapa até o fechamento. Acompanhar a conversão entre etapas ajuda a identificar gargalos.", "alternativeExplanations": {"V": "Incorreto. O número de oportunidades diminui ao longo do funil.", "F": "Correto. O número de oportunidades diminui ao longo do funil."}, "tags": ["funil-de-vendas", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["funil-de-vendas"], "origin": "nabulab"},
];
